export class NewPage extends Component {
    constructor() {
        super();
        this.state = {
            current: null,
            form: null,
        };
    }

    componentDidMount() {
        const form = this.refs.form;
        form.validateFields({
            error: false,
            validate: (data) => {
                this.setState({ current: data });
            },
        });
    }

    onSubmit(e) {
        e.preventDefault();
        this.props.actions.createNewPage(form.state.current);
    }

    render() {
        const { form } = this.state;
        return (
            <form className="page-body form">
                <Form.Group controlId={this.state.current}>
                    <Form.Label>Current Page</Form.Label>
                    <Form.Control type='text' name='current' placeholder='Current Page' onChange={this.onSubmit} />
                </Form.Group>
                <Form.Group controlId={this.state.current}>
                    <Form.Label>Form Data</Form.Label>
                    <Form.Control type='text' name='form' placeholder='Form Data' onChange={this.onSubmit} />
                </Form.Group>
                <div className="form-group">
                    <Form.Button>Create Next page</Form.Button>
                    <Form.Label>New Page</Form.Label>
                    <Form.Control type='text' name='form' placeholder='New Page' onChange={this.onSubmit} />
                </div>
            </form>
        );
    }
}

function mapStateToProps(state) {
    return { form: state.get('form') };
}

export default connect(mapStateToProps, null)(NewPage)

