      <div className="search-result">
        <p>
          This search does not contain any errors in a list. Please check the
          form and handle it accordingly.
        </p>
        <input
          type="text"
          placeholder={query.title}
          value={query.title || ''}
          onChange={this.handleChange.bind(this)}
          className="search-result"
        />
      </div>
    );
  }

  handleChange(event) {
    const query = event.target;
    this.props.query(query, this.props.query.fields);
  }
}

