import { Controller, Get, Post } from "@nestjs/common";
import { TalkService } from './talk.service';
import { CreateTalkDto } from "../dto/create-talk.dto";
import { UpdateTalkDto } from "../dto/update-talk.dto";

@Controller()
export class TalkController {
  constructor(private readonly talkService: TalkService) {}

  @Get('/talk')
  getTalk(@Req() req: any) {
    const token = req.headers['token'];
    const findTalkId = req.query.findUnique as string;
    if (token) {
      try {
        const Talk = await this.talkService.findOne({
          where: {
            token,
          },
          select: ["id", "name", "name2"],
        });

        if (!Talk) throw new NotFoundException();
        return Talk.toObject(findTalkId);
      } catch (err) {
        throw new HttpException(
          {
            status: HttpStatus.INTERNAL_SERVER_ERROR,
            error: `Could not find Talk with id ${findTalkId}`,
          },
          HttpStatus.BAD_REQUEST,
        );
      }
    } else if (!findTalkId) throw new NotFoundException();

    return Talk;
  }
}

