  Param,
  Post,
} from '@nestjs/common';
import { ProductService } from './product.service';
import { CreateProductDto } from './dto/create-product.dto';
import { UpdateProductDto } from './dto/update-product.dto';
import { ProductService } from './product.service';
import { Product } from './product.model';

@Controller('product')
export class ProductController {
  constructor(private readonly productService: ProductService) {}

  @Get()
  async findAll(): Promise<Product[]> {
    return this.productService.findAll();
  }

  @Post()
  async create(@Body() product: CreateProductDto, @Req() req: any) {
    return this.productService.create(product);
  }

  @Get(':id')
  async findById(@Param() params) {
    return this.productService.findById(params.id);
  }

  @Put(':id')
  async update(@Body() product: UpdateProductDto, @Req() req: any) {
    const newProduct = await this.productService.update(
      product,
      {
        $set: req.body.name,
      },
    );
    return this.productService.update(newProduct, {
      ...product,
    });
  }

  @Delete(':id')
  async deleteById(@Param() params) {
    return this.productService.delete(params.id);
  }
}

