def get_ticket(url):
    """Get the ticket from URL or None."""
    if not url or not url.startswith("http://"):
        raise ValueError("url should contain a valid url, and it should be an object")

    headers = {
        'Host': 'api.openssl.com',
        'User-Agent': 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/41.0.2726.99 Safari/537.36',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'
    }

    if url.startswith("http://"):
        url = urlunsplit(url, encoding="utf-8")[0]
    else:
        url = "http://" + str(url)

    return url

